CREATE TABLE staff (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK (role IN ('owner', 'artist')), artist_id TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE customers (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE appointments (id TEXT PRIMARY KEY NOT NULL, customer_id TEXT NOT NULL REFERENCES customers(id), artist_id TEXT REFERENCES staff(id), status TEXT NOT NULL DEFAULT 'submitted', preferred_start_at TEXT NOT NULL, scheduled_start_at TEXT, scheduled_end_at TEXT, description TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX appointments_artist_schedule ON appointments (artist_id, scheduled_start_at);
CREATE TABLE appointment_history (id TEXT PRIMARY KEY NOT NULL, appointment_id TEXT NOT NULL REFERENCES appointments(id), actor_id TEXT REFERENCES staff(id), status TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE availability_blocks (id TEXT PRIMARY KEY NOT NULL, artist_id TEXT NOT NULL REFERENCES staff(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX availability_artist_interval ON availability_blocks (artist_id, starts_at, ends_at);
CREATE TABLE media_assets (id TEXT PRIMARY KEY NOT NULL, appointment_id TEXT NOT NULL REFERENCES appointments(id), uploader_id TEXT NOT NULL REFERENCES staff(id), object_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'pending', approved_by TEXT REFERENCES staff(id), approved_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE calendar_outbox (id TEXT PRIMARY KEY NOT NULL, appointment_id TEXT NOT NULL REFERENCES appointments(id), revision INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (appointment_id, revision));
CREATE TABLE calendar_projection (appointment_id TEXT PRIMARY KEY NOT NULL REFERENCES appointments(id), event_id TEXT NOT NULL, revision INTEGER NOT NULL, state_hash TEXT NOT NULL, last_error TEXT, updated_at TEXT NOT NULL);
